using System.Collections.Generic;
using UnityEngine;
namespace FootballDynasty {
 public sealed class StadiumCrowd:MonoBehaviour {
  private Mesh mesh;private Material kit;private FootballSimulator owner;private readonly List<TextMesh> banners=new List<TextMesh>();private readonly List<Matrix4x4[]> batches=new List<Matrix4x4[]>();
  public void Initialize(FootballSimulator game,Color color){var temporary=GameObject.CreatePrimitive(PrimitiveType.Capsule);mesh=temporary.GetComponent<MeshFilter>().sharedMesh;Destroy(temporary);kit=game.Material(color);kit.enableInstancing=true;var matrices=new List<Matrix4x4>();for(int stand=0;stand<4;stand++){bool longitudinal=stand<2;int sign=stand%2==0?-1:1;int count=longitudinal?76:46;float length=longitudinal?114:71;for(int row=0;row<12;row++)for(int i=0;i<count;i++){if(i%19<2||(Application.isMobilePlatform&&i%2==1))continue;float depth=(longitudinal?39:60)+row*1.3f;float along=-length*.5f+1+i*(length-2)/(count-1);var p=longitudinal?new Vector3(along,row*.8f+1,sign*depth):new Vector3(sign*depth,row*.8f+1,along);matrices.Add(Matrix4x4.TRS(p,Quaternion.identity,new Vector3(.46f,.65f,.4f)));}}for(int i=0;i<matrices.Count;i+=1000)batches.Add(matrices.GetRange(i,System.Math.Min(1000,matrices.Count-i)).ToArray());}
  void Start(){owner=GetComponent<FootballSimulator>();var font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");for(int stand=0;stand<4;stand++){bool longSide=stand<2;int sign=stand%2==0?-1:1;var board=GameObject.CreatePrimitive(PrimitiveType.Cube);board.name="Lona del club";board.transform.SetParent(transform);board.transform.position=longSide?new Vector3(0,1.5f,sign*36):new Vector3(sign*57,1.5f,0);board.transform.localScale=longSide?new Vector3(42,2.3f,.15f):new Vector3(.15f,2.3f,27);board.GetComponent<Renderer>().sharedMaterial=kit;Destroy(board.GetComponent<Collider>());var text=new GameObject("Nombre del club").AddComponent<TextMesh>();text.transform.SetParent(transform);text.transform.position=board.transform.position+(longSide?new Vector3(0,0,-sign*.15f):new Vector3(-sign*.15f,0,0));text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.font=font;text.fontSize=96;text.characterSize=.12f;text.GetComponent<MeshRenderer>().sharedMaterial=font.material;banners.Add(text);}SetColors(kit.color);}
  public void SetColors(Color color){kit.color=color;if(!owner)owner=GetComponent<FootballSimulator>();foreach(var text in banners){text.text=owner.Career.Clubs[owner.ClubId].name.ToUpperInvariant()+" · SIEMPRE CONTIGO";text.color=color.grayscale>.6f?new Color(.12f,.15f,.2f):Color.white;}}
  void LateUpdate(){if(mesh&&kit)foreach(var batch in batches)Graphics.DrawMeshInstanced(mesh,0,kit,batch,batch.Length,null,UnityEngine.Rendering.ShadowCastingMode.Off,true);if(owner&&owner.MatchCamera)foreach(var text in banners)text.transform.rotation=Quaternion.LookRotation(text.transform.position-owner.MatchCamera.transform.position);}
  void OnDestroy(){if(kit)Destroy(kit);}
 }
}
